from pybricks.tools import multitask, run_task, wait

from robot_config import DRIVE_BASE, HUB, LEFT_ATTACHMENT, RIGHT_ATTACHMENT

async def WallStart():
    await wait(0)
    print('WallStart')
    # Reverse into the wall
    DRIVE_BASE.use_gyro(False)
    DRIVE_BASE.settings(straight_speed=200)
    DRIVE_BASE.settings(straight_acceleration=750)
    await DRIVE_BASE.straight(-25)
    await wait(100)
    DRIVE_BASE.use_gyro(True)
    DRIVE_BASE.reset(0, 0)

async def main():
    # Blank,  done to make code multitask
    # Needed due to how the blocks work
    await multitask(
        wait(0),
    )


run_task(main())